    {"name":"Nghị định 94/2024/NĐ-CP", "file":"Additional/94_2024_ND-CP_619415.doc", "status":"file .doc nhị phân, chưa convert sạch bằng CLI; cần dùng Word/LibreOffice nếu muốn trích đầy đủ", "role":"nguồn nhà ở cần kiểm tra thêm"},
    {"name":"QD 50/2023/UBND", "file":"Additional/50_2023_QD-UBND_580638.doc", "status":"đã extract; chỉ dùng nếu liên quan địa phương/quỹ đất", "role":"tham chiếu phụ"}
