html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Luật đầu tư dự án BĐS</title><style>
:root{--bg:#f7f3eb;--ink:#17211b;--muted:#69736c;--line:#d8cfbf;--card:#fffaf1;--accent:#245b45;--red:#9a3c2e;--gold:#b8872e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 Inter,system-ui,Segoe UI,Arial}header{padding:28px clamp(18px,4vw,56px);border-bottom:1px solid var(--line);background:#fbf8f1}h1{font-size:clamp(26px,4vw,48px);line-height:1.05;margin:0 0 10px;letter-spacing:-.04em}.sub{max-width:920px;color:var(--muted);font-size:18px}.wrap{display:grid;grid-template-columns:320px 1fr;gap:24px;padding:24px clamp(18px,4vw,56px)}nav{position:sticky;top:16px;align-self:start;border:1px solid var(--line);background:#fffaf5;border-radius:18px;padding:12px}.navbtn{width:100%;text-align:left;border:0;background:transparent;padding:12px;border-radius:12px;color:var(--muted);cursor:pointer}.navbtn.active{background:var(--accent);color:white}.card{background:var(--card);border:1px solid var(--line);border-radius:24px;padding:24px;box-shadow:0 12px 30px #0000000c}.eyebrow{color:var(--gold);font-weight:700;text-transform:uppercase;font-size:12px;letter-spacing:.08em}h2{font-size:32px;line-height:1.1;margin:6px 0 12px}.q{font-size:22px;font-weight:750;margin:12px 0 18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.box{border:1px solid var(--line);border-radius:16px;padding:16px;background:#fffdf8}.box h3{margin:0 0 8px;font-size:14px;color:var(--accent);text-transform:uppercase;letter-spacing:.06em}ul{margin:0;padding-left:19px}.risk{border-color:#e3b9ae;background:#fff6f3}.risk h3{color:var(--red)}.cite span{display:inline-block;margin:4px 6px 0 0;padding:6px 9px;border:1px solid var(--line);border-radius:999px;background:white;color:#39443d;font-size:13px}.principles{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.pill{border:1px solid var(--line);border-radius:999px;padding:7px 10px;background:white;color:var(--muted);font-size:13px}footer{padding:18px 56px;color:var(--muted);font-size:13px}@media(max-width:850px){.wrap{grid-template-columns:1fr}nav{position:relative}.grid{grid-template-columns:1fr}}
</style></head><body><header><div class="eyebrow">Bản đầu tư BĐS / concise</div><h1 id="title"></h1><div class="sub" id="sub"></div><div class="principles" id="principles"></div></header><main class="wrap"><nav id="nav"></nav><section><article class="card" id="card"></article></section></main><footer>Ghi chú: đây là bản curated ngắn, tập trung quyết định đầu tư; bấm từng gate để xem output/rủi ro/căn cứ.</footer><script>
let DATA,active=0;fetch('investment_bds_flow.json').then(r=>r.json()).then(d=>{DATA=d;init()});
function init(){title.textContent=DATA.title;sub.textContent=DATA.subtitle;principles.innerHTML=DATA.principles.map(p=>`<span class=pill>${p}</span>`).join('');nav.innerHTML=DATA.gates.map((g,i)=>`<button class="navbtn ${i==0?'active':''}" onclick="show(${i})">${g.title}</button>`).join('');show(0)}
function show(i){active=i;document.querySelectorAll('.navbtn').forEach((b,j)=>b.classList.toggle('active',j==i));let g=DATA.gates[i];card.innerHTML=`<div class=eyebrow>Gate ${i}</div><h2>${g.title}</h2><div class=q>${g.investor_question}</div><div class=grid><div class=box><h3>Nhà đầu tư cần quyết</h3><ul>${g.decision.map(x=>`<li>${x}</li>`).join('')}</ul></div><div class=box><h3>Output phải có</h3><p>${g.output}</p></div><div class="box risk"><h3>Rủi ro chính</h3><p>${g.risk}</p></div><div class="box cite"><h3>Căn cứ</h3>${g.citations.map(c=>`<span>${c}</span>`).join('')}</div></div>`}
</script></body></html>'''
(web/'investment_bds_flow.html').write_text(html,encoding='utf-8')
print('wrote investment_bds_flow')
